G1=$(nsg 'fwshift-addresses') || exit 1
# attach fwshift-port1_2: 10.10.0.0/24
G2=$(nsg 'fwshift-port1_2') || exit 1
# attach fwshift-vlan20: 10.20.0.0-10.20.0.49 10.20.0.51-10.20.0.255
G3=$(nsg 'fwshift-vlan20') || exit 1
# attach fwshift-historian: 10.20.0.50
G4=$(nsg 'fwshift-historian') || exit 1
# attach fwshift-port1_3: 10.30.0.0-10.30.0.9 10.30.0.11-10.30.0.63 10.30.0.80-10.30.1.255
G5=$(nsg 'fwshift-port1_3') || exit 1
# attach fwshift-port1_3-2: 10.30.0.10
G6=$(nsg 'fwshift-port1_3-2') || exit 1
# attach fwshift-port1_3-3: 10.30.0.64/28
G7=$(nsg 'fwshift-port1_3-3') || exit 1
# attach fwshift-port1_1: 192.0.2.0/24
G8=$(nsg 'fwshift-port1_1') || exit 1
# attach fwshift-no-rules: ::/0
G9=$(nsg 'fwshift-no-rules') || exit 1

