rules "$G1" <<'FWSHIFT_JSON'
[{"description": "FWShift: rule-150", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.30.0.64/28", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: rule-40", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.30.0.0/23", "sourceType": "CIDR_BLOCK"}]
FWSHIFT_JSON
rules "$G2" <<'FWSHIFT_JSON'
[{"description": "FWShift: rule-150", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.30.0.64/28", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: rule-10", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.20.0.0/24", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 502, "min": 502}}}, {"description": "FWShift: rule-40", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.30.0.0/23", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-130", "destination": "10.20.0.50/32", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 1433, "min": 1433}}}, {"description": "FWShift: rule-40-2", "destination": "10.30.0.0/23", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1"}]
FWSHIFT_JSON
rules "$G3" <<'FWSHIFT_JSON'
[{"description": "FWShift: rule-150", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.30.0.64/28", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: rule-40", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.30.0.0/23", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-10", "destination": "10.10.0.0/24", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 502, "min": 502}}}, {"description": "FWShift: rule-40-2", "destination": "10.30.0.0/23", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1"}]
FWSHIFT_JSON
