[{"description": "FWShift: rule-150", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "10.30.0.64/28", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: rule-40, rule-40-2", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.10.0.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-40, rule-40-2", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.20.0.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-40, rule-40-2", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "10.30.0.0/23", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-40, rule-40-2", "direction": "INGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1", "source": "192.0.2.0/24", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: rule-150", "destination": "0.0.0.0/0", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: rule-40, rule-40-2", "destination": "0.0.0.0/0", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 8}, "isStateless": false, "protocol": "1"}]
